usage:
```ts
import { dsarInstance } from "@dsar/backend";
import { makeS3StorageAdapter } from "@dsar/storage-s3";

const storage = makeS3StorageAdapter({
	bucket: "dsar-artifacts",
	region: "us-east-1",
});

const runtime = dsarInstance({
	adapters: {
		inbound: "stub",
		notifications: "stub",
		storage,
	},
});
```
